def forward(groups):
    task_count = int(groups[0])
    stage_id = int(groups[1])
    compact_value = stage_id * int(1e5) + task_count
    return {'stored': [compact_value], 'layout': [groups[0], groups[1]]}

def inverse(record):
    compact_value = int(record['stored'][0])
    task_count = compact_value % int(1e5)
    stage_id = compact_value // int(1e5)
    return f"Submitting {task_count} missing tasks from ResultStage {stage_id}"
